{"content": """"Verificacao independente da projecao model-facing do browser.

Nao reusa o medidor do ChatGPT: extrai os payloads reais por conta propria,
chama a funcao REAL do repo e reconstroi os elementos a partir do payload
projetado (texto + element_index) para provar que nada se perdeu.

No dump, o tool result aparece como string JSON escapada -- por isso o
caminho e: carregar o dump, colher as strings e decodificar o payload dentro.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

REPO = Path(r"C:\Github\hermes-agent")
SESSIONS = Path(r"C:\Users\Kevyn Lucas\AppData\Local\hermes\sessions")
sys.path.insert(0, str(REPO))

import tiktoken  # noqa: E402

from tools.browser_workstation import project_model_browser_payload  # noqa: E402

ENC = tiktoken.get_encoding("cl100k_base")
LINE = re.compile(
    r'^- \[(?P<ref>@e\d+)\] (?P<role>\S+)'
    r'(?: "(?P<label>(?:[^"\\]|\\.)*)")?'
    r'(?: value="(?P<value>(?:[^"\\]|\\.)*)")?'
    r'(?P<disabled> disabled)?$'
)


def tokens(text: str) -> int:
    return len(ENC.encode(text))


def strings(node) -> list[str]:
    if isinstance(node, str):
        return [node]
    if isinstance(node, dict):
        return [s for value in node.values() for s in strings(value)]
    if isinstance(node, list):
        return [s for value in node for s in strings(value)]
    return []


def real_results() -> list[tuple[str, dict]]:
    """Todo tool result de browser dos dumps reais (com ou sem inventario)."""
    found: list[tuple[str, dict]] = []
    for path in sorted(SESSIONS.glob("request_dump_*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8", errors="replace"))
        except ValueError:
            continue
        for text in strings(data):
            if "Interactive elements" not in text or "snapshot" not in text:
                continue
            start = text.find('{"success"')
            if start < 0:
                continue
            try:
                payload, _ = json.JSONDecoder().raw_decode(text[start:])
            except ValueError:
                continue
            if isinstance(payload, dict) and "snapshot" in payload:
